namespace ldb_ipc_v2 {
inline uint64_t milliseconds() {
  return static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(
    std::chrono::steady_clock::now().time_since_epoch()).count());
}
inline uint32_t processId() {
#ifdef _WIN32
  return GetCurrentProcessId();
#else
  return static_cast<uint32_t>(getpid());
#endif
}
inline void pauseCpu() {
#if defined(_WIN32)
  YieldProcessor();
#elif defined(__i386__) || defined(__x86_64__)
  __builtin_ia32_pause();
#else
  std::atomic_signal_fence(std::memory_order_seq_cst);
#endif
}
inline bool peerAlive(uint32_t pid) {
  if (!pid) { return true; }
#ifdef _WIN32
  HANDLE process = OpenProcess(SYNCHRONIZE, FALSE, pid);
  if (!process) { return GetLastError() != ERROR_INVALID_PARAMETER; }
  const DWORD state = WaitForSingleObject(process, 0);
  CloseHandle(process);
  return state != WAIT_OBJECT_0;
#else
  return kill(static_cast<pid_t>(pid), 0) == 0 || errno != ESRCH;
#endif
}

class Mapping {
  void* m_data = nullptr;
  size_t m_bytes = 0;
  bool m_owner = false;
  bool m_created = false;
  std::string m_name;
#ifdef _WIN32
  HANDLE m_handle = nullptr;
#else
  int m_handle = -1;
#endif
public:
  Mapping(const std::string& name, size_t bytes, bool create, bool allowExisting = false)
    : m_bytes(bytes), m_owner(create) {
#ifdef _WIN32
    m_name = "Local\\LDB-IPC-V2-" + name;
    m_handle = create ? CreateFileMappingA(INVALID_HANDLE_VALUE, nullptr, PAGE_READWRITE,
      0, static_cast<DWORD>(bytes), m_name.c_str()) : OpenFileMappingA(FILE_MAP_ALL_ACCESS, FALSE, m_name.c_str());
    if (!m_handle) { throw std::runtime_error("mapping open/create failed"); }
    m_created = create && GetLastError() != ERROR_ALREADY_EXISTS;
    if (create && !m_created && !allowExisting) {
      CloseHandle(m_handle); m_handle = nullptr;
      throw std::runtime_error("mapping already exists");
    }
    m_owner = m_created;
    m_data = MapViewOfFile(m_handle, FILE_MAP_ALL_ACCESS, 0, 0, bytes);
    if (!m_data) { CloseHandle(m_handle); m_handle = nullptr; throw std::runtime_error("mapping view failed"); }
#else
    m_name = "/LDB-IPC-V2-" + name;
    m_handle = shm_open(m_name.c_str(), create ? O_CREAT | O_EXCL | O_RDWR : O_RDWR, 0600);
    m_created = create && m_handle >= 0;
    if (m_handle < 0 && create && allowExisting && errno == EEXIST) {
      m_handle = shm_open(m_name.c_str(), O_RDWR, 0600);
    }
    m_owner = m_created;
    if (m_handle < 0) { throw std::runtime_error("mapping open/create failed"); }
    if (m_created && ftruncate(m_handle, static_cast<off_t>(bytes))) {
      close(m_handle); shm_unlink(m_name.c_str()); throw std::runtime_error("mapping resize failed");
    }
    struct stat info {};
    if (fstat(m_handle, &info) || info.st_size != static_cast<off_t>(bytes)) {
      close(m_handle); if (m_created) { shm_unlink(m_name.c_str()); }
      throw std::runtime_error("mapping size mismatch");
    }
    m_data = mmap(nullptr, bytes, PROT_READ | PROT_WRITE, MAP_SHARED, m_handle, 0);
    if (m_data == MAP_FAILED) {
      close(m_handle); if (m_created) { shm_unlink(m_name.c_str()); }
      throw std::runtime_error("mapping view failed");
    }
#endif
  }
  Mapping(const Mapping&) = delete;
  Mapping& operator=(const Mapping&) = delete;
  ~Mapping() {
#ifdef _WIN32
    if (m_data) { UnmapViewOfFile(m_data); }
    if (m_handle) { CloseHandle(m_handle); }
#else
    if (m_data) { munmap(m_data, m_bytes); }
    if (m_handle >= 0) { close(m_handle); }
    if (m_owner) { shm_unlink(m_name.c_str()); }
#endif
  }
  bool created() const { return m_created; }
  void* data() const { return m_data; }
  size_t bytes() const { return m_bytes; }
};

struct alignas(64) WakeState {
  std::atomic<uint32_t> armed { 0 };
  std::atomic<uint32_t> epoch { 0 };
};
// A wake is only a hint. There is exactly one waiter for each direction/credit.
// Windows uses persistent auto-reset events; Linux uses a process-shared futex.
class Event {
  WakeState& m_shared;
#ifdef _WIN32
  HANDLE m_handle = nullptr;
#endif
public:
#ifdef LDB_IPC_V2_TEST
  inline static bool failNextWait = false;
#endif
  Event(WakeState& shared, const std::string& name) : m_shared(shared) {
#ifdef _WIN32
    m_handle = CreateEventA(nullptr, FALSE, FALSE, ("Local\\LDB-IPC-V2-" + name).c_str());
    if (!m_handle) { throw std::runtime_error("event create failed"); }
#else
    (void)name;
#endif
  }
  Event(const Event&) = delete;
  ~Event() {
#ifdef _WIN32
    if (m_handle) { CloseHandle(m_handle); }
#endif
  }
  bool notify() {
    if (!m_shared.armed.load(std::memory_order_seq_cst)) { return true; }
    m_shared.epoch.fetch_add(1, std::memory_order_release);
#ifdef _WIN32
    return SetEvent(m_handle) != FALSE;
#else
    return syscall(SYS_futex, &m_shared.epoch, FUTEX_WAKE, 1, nullptr, nullptr, 0) >= 0;
#endif
  }
  bool wait(uint32_t epoch, uint32_t timeoutMs) {
#ifdef LDB_IPC_V2_TEST
    if (failNextWait) { failNextWait = false; return false; }
#endif
#ifdef _WIN32
    (void)epoch;
    return WaitForSingleObject(m_handle, timeoutMs) != WAIT_FAILED;
#else
    const timespec timeout { static_cast<time_t>(timeoutMs / 1000),
      static_cast<long>(timeoutMs % 1000) * 1000000L };
    const long result = syscall(SYS_futex, &m_shared.epoch, FUTEX_WAIT, epoch, &timeout, nullptr, 0);
    return result == 0 || errno == EAGAIN || errno == EINTR || errno == ETIMEDOUT;
#endif
  }
};
}
